import{x as d,o as e,c as r,a9 as a}from"./chunks/framework.DxG24V0C.js";const o="/agentsrc/images/codex/article-index-architecture.svg",g=JSON.parse('{"title":"Codex 源码精读","description":"","frontmatter":{"title":"Codex 源码精读"},"headers":[],"relativePath":"codex/index.md","filePath":"codex/index.md","lastUpdated":1787409644000}'),n={name:"codex/index.md"};function c(s,t,i,l,h,p){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="codex-源码精读" tabindex="-1">Codex 源码精读 <a class="header-anchor" href="#codex-源码精读" aria-label="Permalink to &quot;Codex 源码精读&quot;">​</a></h1><blockquote><p>OpenAI 官方开源终端编程 Agent 源码深度解析</p></blockquote><p>这里是「<strong>Codex 源码精读</strong>」专栏，逐行拆解 OpenAI 官方出品的本地编程 Agent。</p><p>不同于 Claude Code 和 OpenCode，Codex 选择 <strong>Rust</strong> 作为核心语言，拥有更激进的跨平台沙箱、完整的 Agent 树编排、以及独特的 event-driven reactor 主循环。本系列逐章拆解它的 100+ crates，讲清架构选型背后的工程哲学。</p><h2 id="文章列表" tabindex="-1">文章列表 <a class="header-anchor" href="#文章列表" aria-label="Permalink to &quot;文章列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>文章</th><th>类型</th><th>字数</th></tr></thead><tbody><tr><td>1</td><td><a href="/agentsrc/codex/01-overview.html">Codex 全景：架构与定位</a></td><td>源码解析</td><td>~16,000 字</td></tr><tr><td>2</td><td><a href="/agentsrc/codex/02-mainloop.html">主循环：Submission 驱动的 Turn 系统</a></td><td>源码解析</td><td>~13,000 字</td></tr><tr><td>3</td><td><a href="/agentsrc/codex/03-context.html">上下文组合与增量注入</a></td><td>源码解析</td><td>~14,000 字</td></tr><tr><td>4</td><td><a href="/agentsrc/codex/04-compact.html">Compact 系统：3 种压缩机制</a></td><td>源码解析</td><td>~19,000 字</td></tr><tr><td>5</td><td><a href="/agentsrc/codex/05-multi-agents.html">多 Agent 编排架构</a></td><td>源码解析</td><td>~25,000 字</td></tr><tr><td>6</td><td><a href="/agentsrc/codex/06-tools-sandbox.html">工具系统与安全沙箱</a></td><td>源码解析</td><td>~23,000 字</td></tr><tr><td>7</td><td><a href="/agentsrc/codex/07-models.html">模型管理与 Provider 抽象</a></td><td>源码解析</td><td>~20,000 字</td></tr><tr><td>8</td><td><a href="/agentsrc/codex/08-philosophy.html">Codex vs CC 设计哲学对比</a></td><td>源码解析</td><td>~14,000 字</td></tr></tbody></table><h2 id="关于系列" tabindex="-1">关于系列 <a class="header-anchor" href="#关于系列" aria-label="Permalink to &quot;关于系列&quot;">​</a></h2><p>本系列基于 Codex 源码仓库（<a href="https://github.com/openai/codex" target="_blank" rel="noreferrer">GitHub</a>）编写，核心分析范围：</p><ul><li><strong>源码层</strong>：<code>codex-rs/</code> ≈ <strong>100+ 个 crate</strong>，核心在 <code>codex-core</code></li><li><strong>构建系统</strong>：Bazel + Cargo（工程规模相当但构建哲学不同）</li><li><strong>技术栈</strong>：Rust + tokio async + ratatui + SQLite + MCP + WebSocket</li><li><strong>特色</strong>：每篇文章都附带「Codex vs Claude Code」架构对比</li></ul><h2 id="整体架构速览" tabindex="-1">整体架构速览 <a class="header-anchor" href="#整体架构速览" aria-label="Permalink to &quot;整体架构速览&quot;">​</a></h2><p>以下是 Codex 核心引擎 <code>codex-core</code> 的反应器 + turn 流程：</p><p><img src="'+o+'" alt="Codex 反应器架构：submission_loop 分发 Ops，run_turn 驱动采样与工具"></p><h2 id="三个终端-agent-对比" tabindex="-1">三个终端 Agent 对比 <a class="header-anchor" href="#三个终端-agent-对比" aria-label="Permalink to &quot;三个终端 Agent 对比&quot;">​</a></h2><p>本博客同时覆盖 Claude Code、OpenCode 和 Codex，三者的核心差异速览：</p><table tabindex="0"><thead><tr><th>维度</th><th>Claude Code</th><th>OpenCode</th><th>Codex</th></tr></thead><tbody><tr><td>语言</td><td>TypeScript</td><td>TypeScript</td><td>Rust</td></tr><tr><td>主循环</td><td>continuation-driven polling</td><td>while-true loop with Effect-TS</td><td>event-driven reactor (channel)</td></tr><tr><td>沙箱</td><td>无</td><td>无</td><td>跨平台沙箱</td></tr><tr><td>多 Agent</td><td>跨进程 Swarm + 同进程 AgentTool</td><td>task 工具 spawn</td><td>原生 Agent Tree</td></tr><tr><td>压缩</td><td>5 级（前 4 级纯数据结构）</td><td>2 级</td><td>3 种实现（全部调 LLM）</td></tr><tr><td>认证</td><td>API Key</td><td>API Key</td><td>ChatGPT OAuth + API Key</td></tr><tr><td>IDE 集成</td><td>终端内使用</td><td>终端内使用</td><td>App Server 守护进程</td></tr></tbody></table>',15)])])}const u=d(n,[["render",c]]);export{g as __pageData,u as default};
